export default defineSkill(skill,{instructions:READING_INSTRUCTIONS+' Tieba: page starts at 1; legacy forum pn uses a row offset. Consume nextOffset before nextPage. Source.nextOffset continues text through textOffset. searchTopics, getTopics and getTopic use the website PC JSON APIs. readCurrent reads the loaded page. forum filters names in the current search response. Main post floor is 1; loadedCount counts top-level floors before slicing, nestedReplyCount counts returned nested replies. includeImages/maxImages/imageOffset selects pictures; readImages({urls:[img.currentSrc || img.src]}) attaches a specific picture through the extension background. Return the imageContext object from js_exec so the host can attach its pixels. imageContext.delivery reports attachment status. getUser uses the portrait id in the author link. Results follow the readerVersion/sources dehydration contract.'});
